(() => {
  return [1,2,3,4].map(n => {
    const td = document.querySelector('td.board-column-'+n);
    const title = td.querySelector('.board-column-title') ? td.querySelector('.board-column-title').textContent.trim() : '';
    const cards = [...td.querySelectorAll('.draggable-item')].map(c => ({id: c.getAttribute('data-task-id'), col: c.getAttribute('data-column-id'), title: c.querySelector('a') ? c.querySelector('a').textContent.trim().slice(0,40) : ''}));
    return {n, title, cards};
  });
})()

(() => {
  const inputs = [...document.querySelectorAll('input, textarea, select')].filter(e => /date|due/i.test(e.id + ' ' + e.name + ' ' + (e.getAttribute('placeholder')||'')));
  return inputs.map(e => ({tag: e.tagName, id: e.id, name: e.name, type: e.type, value: e.value, title: e.getAttribute('title'), placeholder: e.getAttribute('placeholder')}));
})()

(() => {
  return [...document.querySelectorAll('form')].map((f,i) => ({
    i, id: f.id, action: (f.getAttribute('action')||'').slice(0,80),
    hasDateDue: !!f.querySelector('#form-date_due'),
    buttons: [...f.querySelectorAll('button[type=submit], input[type=submit]')].map(b => (b.textContent||b.value||'').trim())
  }));
})()

(() => {
  const txt = document.body.innerText;
  const idx = txt.search(/Due date/i);
  const comments = [...document.querySelectorAll('.comment .comment-content, div[id^="comment-"] .markdown, .comments .markdown')].map(e=>e.textContent.trim());
  return {dueDateContext: idx >= 0 ? txt.slice(idx, idx+80).replace(/\n+/g,' | ') : null, title: document.title, comments};
})()

(() => {
  const side = document.querySelector('#sidebar, .sidebar, aside') || document.body;
  const items = [...side.querySelectorAll('ul li')].map(li => li.innerText.replace(/\s+/g,' ').trim()).filter(t=>t);
  const desc = document.querySelector('#task-description, article p, .task-description');
  const comments = [...document.querySelectorAll('.comment .comment-content, div[id^="comment-"] .markdown, .comments .markdown, article.md-comment')].map(e=>e.innerText.trim());
  return {title: document.title, details: items.slice(0,30), description: desc ? desc.innerText.trim() : null, comments};
})()

